namespace {const Colour bg(0xff10151d),panelColour(0xff1a222e),ink(0xffe9f0f7),muted(0xff8394a7),accent(0xff56e5c7),line(0xff2b3747);}
struct SynthMavenEditor::Style:LookAndFeel_V4{
 Style(){setColour(TextButton::buttonColourId,panelColour);setColour(TextButton::textColourOffId,muted);setColour(TextButton::textColourOnId,accent);setColour(TextButton::buttonOnColourId,Colour(0xff253d40));setColour(ComboBox::backgroundColourId,panelColour);setColour(ComboBox::outlineColourId,line);setColour(ComboBox::textColourId,ink);setColour(PopupMenu::backgroundColourId,panelColour);setColour(PopupMenu::textColourId,ink);setColour(ListBox::backgroundColourId,bg);setColour(TextEditor::backgroundColourId,panelColour);setColour(TextEditor::textColourId,ink);setColour(TextEditor::outlineColourId,line);setColour(Slider::textBoxTextColourId,ink);setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);setColour(Slider::textBoxBackgroundColourId,Colours::transparentBlack);}
 void drawRotarySlider(Graphics&g,int x,int y,int w,int h,float pos,float start,float end,Slider&)override{float r=jmin(w,h)*.5f-7,cx=x+w*.5f,cy=y+h*.5f;Path track;track.addCentredArc(cx,cy,r,r,0,start,end,true);g.setColour(line);g.strokePath(track,PathStrokeType(3));Path arc;arc.addCentredArc(cx,cy,r,r,0,start,start+pos*(end-start),true);g.setColour(accent);g.strokePath(arc,PathStrokeType(3));g.setColour(Colour(0xff222e3d));g.fillEllipse(cx-r+6,cy-r+6,2*r-12,2*r-12);float a=start+pos*(end-start);g.setColour(ink);g.drawLine(cx+std::sin(a)*(r-15),cy-std::cos(a)*(r-15),cx+std::sin(a)*(r-7),cy-std::cos(a)*(r-7),2);}
 void drawButtonBackground(Graphics&g,Button&b,const Colour&,bool over,bool)override{g.setColour(b.getToggleState()?Colour(0xff263f42):over?Colour(0xff283544):panelColour);g.fillRoundedRectangle(b.getLocalBounds().toFloat(),5);if(b.getToggleState()){g.setColour(accent);g.fillRect(8,b.getHeight()-2,b.getWidth()-16,2);}}
};
struct SynthMavenEditor::Control:Component{
 SynthMavenProcessor&p;int index;Label label;Slider knob;ComboBox choices;bool choice=false;std::unique_ptr<AudioProcessorValueTreeState::SliderAttachment> attachment;
 Control(SynthMavenProcessor&proc,int i):p(proc),index(i){addAndMakeVisible(label);String title=p.parameterLabel(i);if(i==1)title="ATTACK";if(i==2)title="DECAY";if(i==3)title="SUSTAIN";if(i==4)title="RELEASE";if(i==37)title="VOICE MODE";if(i==38)title="GLIDE";if(i==96)title="BRIGHTNESS";if(i==97)title="TIMBRE";if(i==98)title="MOTION";label.setText(title,dontSendNotification);label.setJustificationType(Justification::centred);label.setColour(Label::textColourId,muted);label.setFont(Font(11,Font::bold));addAndMakeVisible(knob);knob.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);knob.setTextBoxStyle(Slider::TextBoxBelow,false,94,18);knob.setRange(0,1);knob.setDoubleClickReturnValue(true,sm_get_parameter_default());knob.textFromValueFunction=[this](double v){return p.parameterText(index,(float)v);};knob.setPopupDisplayEnabled(false,false,this);auto d=sm_parameter_info(p.selectedEngine(),i);choice=d.choices!=0;if(choice){knob.setVisible(false);addAndMakeVisible(choices);for(int v=d.minimum;v<=d.maximum;v++)choices.addItem(sm_parameter_choice(p.selectedEngine(),i,v),v-d.minimum+1);choices.onChange=[this]{auto*param=p.parameters.getParameter("p"+String(index));param->beginChangeGesture();param->setValueNotifyingHost((float)choices.getSelectedItemIndex()/jmax(1,choices.getNumItems()-1));param->endChangeGesture();};refresh();}else attachment=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.parameters,"p"+String(i),knob);knob.textFromValueFunction=[this](double v){return p.parameterText(index,(float)v);};knob.setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);knob.setTextBoxIsEditable(false);knob.updateText();setTooltip();}
 double sm_get_parameter_default(){auto d=sm_parameter_info(p.selectedEngine(),index);return d.maximum>d.minimum?(double)(d.initial-d.minimum)/(d.maximum-d.minimum):0;}
 void setTooltip(){knob.setTooltip(p.parameterLabel(index)+" / drag to edit, double-click to reset / DAW parameter p"+String(index));}
 void refresh(){if(choice){auto*v=p.parameters.getRawParameterValue("p"+String(index));if(v)choices.setSelectedItemIndex(roundToInt(v->load()*(choices.getNumItems()-1)),dontSendNotification);}}
 void resized()override{choices.setBounds(5,40,getWidth()-10,31);label.setBounds(0,0,getWidth(),20);knob.setBounds(0,18,getWidth(),getHeight()-18);}
};
struct SynthMavenEditor::Panel:Component{
 SynthMavenProcessor&p;OwnedArray<Control> controls;struct Group{String title;std::vector<int> ids;};std::vector<Group> groups;std::vector<std::pair<String,Rectangle<int>>> headings;
 explicit Panel(SynthMavenProcessor&proc):p(proc){}
 void configure(int tab){controls.clear();groups.clear();int n=sm_parameter_count();auto add=[&](String title,std::function<bool(int,String)>accept){Group g;g.title=title;for(int i=0;i<n;i++){String s=p.parameterLabel(i);if(p.visibleParameter(i)&&accept(i,s)){g.ids.push_back(i);auto*c=controls.add(new Control(p,i));addAndMakeVisible(c);}}if(!g.ids.empty())groups.push_back(std::move(g));};
 if(tab==0){add("ENGINE / "+factoryEngine(),[&](int i,String){return i>=118&&i<126;});add("AMPLITUDE & FILTER",[](int i,String s){return (i>=1&&i<=5)||(i>=37&&i<=39);});add("PERFORMANCE MACROS",[](int,String s){return s=="BRITE"||s=="TIMBR"||s=="MOTN"||s=="SPACE";});}
 else if(tab==1){add("LFO 1",[](int i,String){return i>=9&&i<=16;});add("LFO 2 & 3 / ENVELOPE 2",[](int i,String){return (i>=53&&i<=59)||(i>=92&&i<=95);});add("MODULATION MATRIX / SLOTS 1-6",[](int i,String){return i>=60&&i<=77;});add("MODULATION MATRIX / SLOTS 7-12",[](int i,String){return i>=100&&i<=117;});add("ARPEGGIATOR",[](int i,String){return i>=17&&i<=27;});}
 else if(tab==2){add("EFFECTS & MASTER",[](int i,String s){return i>=126||(i>=33&&i<=36)||(i>=78&&i<=81);});}
 else add("ALL SYNTHESIS PARAMETERS",[](int,String){return true;});resized();}
 String factoryEngine(){return SynthMavenProcessor::factory()[(size_t)p.getCurrentProgram()].engine;}
 void paint(Graphics&g)override{g.setColour(panelColour);g.fillRoundedRectangle(getLocalBounds().toFloat(),8);for(auto&h:headings){g.setColour(muted);g.setFont(Font(11,Font::bold));g.drawText(h.first,h.second,Justification::centredLeft);g.setColour(line);g.drawHorizontalLine(h.second.getBottom()+3,16,getWidth()-16);}}
 void resized()override{headings.clear();int y=8,ci=0;int cols=jmax(4,getWidth()/112),cw=(getWidth()-24)/cols;for(auto&group:groups){headings.push_back({group.title,{18,y,getWidth()-36,28}});y+=40;for(size_t j=0;j<group.ids.size();j++)controls[ci++]->setBounds(12+((int)j%cols)*cw,y+((int)j/cols)*112,cw,106);y+=((int)group.ids.size()+cols-1)/cols*112+16;}if(getHeight()!=y)setSize(getWidth(),y);}
};
SynthMavenEditor::SynthMavenEditor(SynthMavenProcessor&p):AudioProcessorEditor(p),processor(p),browser("Factory presets",this),keyboard(p.keyboard,MidiKeyboardComponent::horizontalKeyboard){style=std::make_unique<Style>();setLookAndFeel(style.get());int bytes=0;auto*data=BinaryData::getNamedResource(BinaryData::namedResourceList[0],bytes);logo=Drawable::createFromImageData(data,(size_t)bytes);
 for(Component*c:std::initializer_list<Component*>{&search,&engineFilter,&browser,&previous,&next,&save,&import,&panic,&soundTab,&modTab,&fxTab,&allTab,&viewport,&keyboard})addAndMakeVisible(c);
 search.setTextToShowWhenEmpty("Search factory sounds...",muted);search.onTextChange=[this]{filter();};engineFilter.addItem("ALL ENGINES",1);for(int i=0;i<sm_engine_count();i++)engineFilter.addItem(sm_engine_name(i),i+2);engineFilter.setSelectedId(1);engineFilter.onChange=[this]{filter();};browser.setRowHeight(47);browser.setColour(ListBox::outlineColourId,line);browser.setOutlineThickness(1);
 previous.onClick=[this]{selectRelative(-1);};next.onClick=[this]{selectRelative(1);};save.onClick=[this]{openPreset(true);};import.onClick=[this]{openPreset(false);};panic.onClick=[this]{processor.requestPanic();};
 int i=0;for(auto*b:{&soundTab,&modTab,&fxTab,&allTab}){int index=i++;b->setClickingTogglesState(true);b->setRadioGroupId(100);b->onClick=[this,index]{tab=index;rebuild();};}soundTab.setToggleState(true,dontSendNotification);
 panel=std::make_unique<Panel>(p);viewport.setViewedComponent(panel.get(),false);viewport.setScrollBarsShown(true,false);keyboard.setAvailableRange(24,96);keyboard.setLowestVisibleKey(48);keyboard.setKeyWidth(23);keyboard.setColour(MidiKeyboardComponent::whiteNoteColourId,Colour(0xffdce5ee));keyboard.setColour(MidiKeyboardComponent::blackNoteColourId,bg);keyboard.setColour(MidiKeyboardComponent::keyDownOverlayColourId,accent.withAlpha(.6f));
 setResizable(true,true);setResizeLimits(1040,720,1800,1200);setSize(1180,880);filter();rebuild();startTimerHz(24);}
SynthMavenEditor::~SynthMavenEditor(){stopTimer();viewport.setViewedComponent(nullptr,false);setLookAndFeel(nullptr);}
void SynthMavenEditor::filter(){filtered.clear();String q=search.getText().trim();int e=engineFilter.getSelectedId()-2;const auto&f=processor.factory();for(size_t i=0;i<f.size();i++)if((e<0||f[i].engineIndex==e)&&(q.isEmpty()||f[i].name.containsIgnoreCase(q)||f[i].engine.containsIgnoreCase(q)))filtered.push_back((int)i);browser.updateContent();int row=-1;for(size_t i=0;i<filtered.size();i++)if(filtered[i]==processor.getCurrentProgram())row=(int)i;browser.selectRow(row,true,false);repaint();}
int SynthMavenEditor::getNumRows(){return (int)filtered.size();}
void SynthMavenEditor::paintListBoxItem(int row,Graphics&g,int w,int h,bool selected){if(!isPositiveAndBelow(row,(int)filtered.size()))return;auto&f=processor.factory()[(size_t)filtered[(size_t)row]];g.fillAll(selected?Colour(0xff203d3e):bg);if(selected){g.setColour(accent);g.fillRect(0,0,3,h);}g.setFont(Font(13,Font::bold));g.setColour(selected?accent:ink);g.drawText(f.name,14,5,w-20,20,Justification::centredLeft);g.setFont(10);g.setColour(muted);g.drawText(f.engine+" / "+String(filtered[(size_t)row]+1),14,26,w-20,15,Justification::centredLeft);}
void SynthMavenEditor::selectedRowsChanged(int row){if(isPositiveAndBelow(row,(int)filtered.size()))processor.setCurrentProgram(filtered[(size_t)row]);}
void SynthMavenEditor::selectRelative(int d){int n=processor.getNumPrograms();processor.setCurrentProgram((processor.getCurrentProgram()+d+n)%n);}
void SynthMavenEditor::rebuild(){panel->configure(tab);panel->setSize(viewport.getMaximumVisibleWidth()-2,panel->getHeight());viewport.setViewPosition(0,0);repaint();}
void SynthMavenEditor::timerCallback(){for(auto*c:panel->controls)c->refresh();if(lastProgram!=processor.getCurrentProgram()){lastProgram=processor.getCurrentProgram();filter();rebuild();}repaint(scopeBounds);repaint(headerBounds);}
void SynthMavenEditor::resized(){int w=getWidth(),h=getHeight();headerBounds={248,12,w-264,64};search.setBounds(16,96,214,34);engineFilter.setBounds(16,140,214,31);browser.setBounds(16,182,214,h-216);int x=w-312;previous.setBounds(x-82,26,34,31);next.setBounds(x-42,26,34,31);import.setBounds(x,26,82,31);save.setBounds(x+90,26,72,31);panic.setBounds(x+170,26,74,31);
 int tx=250,tw=(w-266)/4;for(auto*b:{&soundTab,&modTab,&fxTab,&allTab}){b->setBounds(tx,96,tw-7,32);tx+=tw;}scopeBounds={250,140,w-266,88};viewport.setBounds(250,240,w-266,h-356);if(panel)panel->setSize(viewport.getMaximumVisibleWidth()-2,panel->getHeight());keyboard.setBounds(250,h-100,w-266,72);}
void SynthMavenEditor::paint(Graphics&g){g.fillAll(bg);g.setColour(line);g.drawHorizontalLine(80,16,getWidth()-16);if(logo)logo->drawWithin(g,Rectangle<float>(16,8,214,58),RectanglePlacement::centred,1);g.setFont(9);g.setColour(muted);g.drawText("SOFTWARE INSTRUMENT / 0.1",16,67,214,12,Justification::centred);
 auto&f=processor.factory()[(size_t)processor.getCurrentProgram()];g.setColour(accent);g.setFont(11);g.drawText(f.engine+"  /  FACTORY",260,17,250,16,Justification::centredLeft);g.setColour(ink);g.setFont(Font(22,Font::bold));g.drawText(processor.displayName(),260,36,getWidth()-670,30,Justification::centredLeft);
 g.setColour(panelColour);g.fillRoundedRectangle(scopeBounds.toFloat(),7);g.setColour(line);g.drawHorizontalLine(scopeBounds.getCentreY(),scopeBounds.getX()+12,scopeBounds.getRight()-12);Path path;unsigned head=processor.scopeWrite.load();for(unsigned i=0;i<512;i++){float v=processor.scope[(head+i)%512].load();float x=scopeBounds.getX()+12+(scopeBounds.getWidth()-24)*i/511.f,y=scopeBounds.getCentreY()-v*scopeBounds.getHeight()*.42f;if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour(accent.withAlpha(.85f));g.strokePath(path,PathStrokeType(1.3f));g.setFont(9);g.setColour(muted);g.drawText("OUTPUT / STEREO",scopeBounds.reduced(12,6),Justification::topLeft);g.drawText(String((int)filtered.size())+" SOUNDS",16,getHeight()-28,214,16,Justification::centredLeft);float level=processor.peak.load();g.setColour(level>.98f?Colour(0xffffad66):accent);g.fillRoundedRectangle((float)getWidth()-108,66,jlimit(0.f,1.f,level)*74,3,1);}
void SynthMavenEditor::openPreset(bool writing){chooser=std::make_unique<FileChooser>(writing?"Save SynthMaven preset":"Import SynthMaven preset or DX7 SysEx",File::getSpecialLocation(File::userDocumentsDirectory),writing?"*.synthmaven":"*.synthmaven;*.syx");Component::SafePointer<SynthMavenEditor> safe(this);chooser->launchAsync(FileBrowserComponent::canSelectFiles|(writing?FileBrowserComponent::saveMode|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode),[safe,writing](const FileChooser&fc){if(!safe)return;auto file=fc.getResult();if(file==File())return;if(writing)safe->processor.savePreset(file.withFileExtension("synthmaven"));else{String error;if(file.hasFileExtension("syx")){auto names=SynthMavenProcessor::dx7VoiceNames(file,error);if(names.isEmpty()){AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Import failed",error);return;}PopupMenu menu;for(int i=0;i<names.size();i++)menu.addItem(i+1,String(i+1)+" / "+names[i]);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&safe->import),[safe,file](int voice){if(!safe||voice<=0)return;String problem;if(!safe->processor.loadPreset(file,problem,voice-1))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Import failed",problem);});}else if(!safe->processor.loadPreset(file,error))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Import failed",error);}});}
